
"use client";

import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { demoCategories, demoProducts, formatPrice, type Category, type Product } from "@/lib/menu";
import { Plus, Pencil, Trash2, LogOut, Coffee, Save, X, ImagePlus, RefreshCw } from "lucide-react";

type ProductForm = { id?: string; name: string; description: string; price: string; category_id: string; image_url: string; available: boolean; featured: boolean; sort_order: string };
const blankForm = (categoryId = ""): ProductForm => ({ name: "", description: "", price: "", category_id: categoryId, image_url: "", available: true, featured: false, sort_order: "0" });


function getMenuImagePath(value: string | null | undefined): string {
  if (!value) return "";
  if (!value.startsWith("http")) return value;

  try {
    const pathname = new URL(value).pathname;
    const match = pathname.match(
      /\/storage\/v1\/object\/(?:sign|public|authenticated)\/menu-images\/(.+)$/
    );
    return match ? decodeURIComponent(match[1]) : value;
  } catch {
    return value;
  }
}

export default function AdminPage() {
  const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
      const [signedIn, setSignedIn] = useState(false);
        const [loading, setLoading] = useState(true);
          const [busy, setBusy] = useState(false);
            const [notice, setNotice] = useState("");
              const [categories, setCategories] = useState<Category[]>(demoCategories);
                const [products, setProducts] = useState<Product[]>(demoProducts);
                  const [form, setForm] = useState<ProductForm | null>(null);
                    const [categoryName, setCategoryName] = useState("");
                      const [showCategoryForm, setShowCategoryForm] = useState(false);

                        useEffect(() => {
                            let mounted = true;
                                async function init() {
                                      if (!supabase) { setLoading(false); return; }
                                            const { data } = await supabase.auth.getSession();
                                                  if (mounted && data.session) {
                                                          setSignedIn(true);
                                                                  await loadData();
                                                                        }
                                                                              if (mounted) setLoading(false);
                                                                                  }
                                                                                      void init();
                                                                                          if (!supabase) return;
                                                                                              const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => {
                                                                                                    setSignedIn(Boolean(session));
                                                                                                          if (session) void loadData();
                                                                                                              });
                                                                                                                  return () => { mounted = false; listener.subscription.unsubscribe(); };
                                                                                                                    }, []);

                                                                                                                      async function loadData() {
                                                                                                                          if (!supabase) return;
                                                                                                                              setBusy(true); setNotice("");
                                                                                                                                  const [cats, prods] = await Promise.all([
                                                                                                                                        supabase.from("categories").select("id,name,sort_order").order("sort_order"),
                                                                                                                                              supabase.from("products").select("id,category_id,name,description,price,image_url,available,featured,sort_order").order("sort_order")
                                                                                                                                                  ]);
                                                                                                                                                      if (cats.error || prods.error) setNotice(`تعذّر تحميل البيانات: ${cats.error?.message || prods.error?.message}`);
                                                                                                                                                          else {
                                                                                                                                                                setCategories((cats.data || []) as Category[]);
                                                                                                                                                                      const productsWithFreshUrls = await Promise.all(
        ((prods.data || []) as Product[]).map(async (product) => {
          const imagePath = getMenuImagePath(product.image_url);
          if (!imagePath) return product;
          const { data } = await supabase!.storage
            .from("menu-images")
            .createSignedUrl(imagePath, 60 * 60);
          return { ...product, image_url: data?.signedUrl || product.image_url };
        })
      );
      setProducts(productsWithFreshUrls);
                                                                                                                                                                          }
                                                                                                                                                                              setBusy(false);
                                                                                                                                                                                }

                                                                                                                                                                                  async function login(e: React.FormEvent) {
                                                                                                                                                                                      e.preventDefault();
                                                                                                                                                                                          if (!supabase) return;
                                                                                                                                                                                              setBusy(true); setNotice("");
                                                                                                                                                                                                  const { error } = await supabase.auth.signInWithPassword({ email, password });
                                                                                                                                                                                                      if (error) setNotice("تعذّر تسجيل الدخول: تأكد من البريد وكلمة المرور ومن إعدادات Supabase.");
                                                                                                                                                                                                          else { setSignedIn(true); await loadData(); }
                                                                                                                                                                                                              setBusy(false);
                                                                                                                                                                                                                }

                                                                                                                                                                                                                  async function logout() {
                                                                                                                                                                                                                      if (!supabase) return;
                                                                                                                                                                                                                          await supabase.auth.signOut(); setSignedIn(false);
                                                                                                                                                                                                                            }

                                                                                                                                                                                                                              async function saveProduct(e: React.FormEvent) {
                                                                                                                                                                                                                                  e.preventDefault();
                                                                                                                                                                                                                                      if (!supabase || !form) return;
                                                                                                                                                                                                                                          const price = Number(form.price);
                                                                                                                                                                                                                                              if (!form.name.trim() || !Number.isFinite(price) || price < 0 || !form.category_id) {
                                                                                                                                                                                                                                                    setNotice("أدخل اسم الصنف والسعر الصحيح واختر القسم."); return;
                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                            setBusy(true); setNotice("");
                                                                                                                                                                                                                                                                const payload = {
                                                                                                                                                                                                                                                                      name: form.name.trim(), description: form.description.trim(), price,
                                                                                                                                                                                                                                                                            category_id: form.category_id, image_url: getMenuImagePath(form.image_url.trim()),
                                                                                                                                                                                                                                                                                  available: form.available, featured: form.featured, sort_order: Number(form.sort_order) || 0
                                                                                                                                                                                                                                                                                      };
                                                                                                                                                                                                                                                                                          const result = form.id
                                                                                                                                                                                                                                                                                                ? await supabase.from("products").update(payload).eq("id", form.id)
                                                                                                                                                                                                                                                                                                      : await supabase.from("products").insert(payload);
                                                                                                                                                                                                                                                                                                          if (result.error) setNotice(`لم يتم حفظ الصنف: ${result.error.message}`);
                                                                                                                                                                                                                                                                                                              else { setForm(null); setNotice("تم حفظ الصنف."); await loadData(); }
                                                                                                                                                                                                                                                                                                                  setBusy(false);
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                      async function deleteProduct(id: string) {
                                                                                                                                                                                                                                                                                                                          if (!supabase || !window.confirm("متأكد أنك تريد حذف هذا الصنف؟")) return;
                                                                                                                                                                                                                                                                                                                              setBusy(true);
                                                                                                                                                                                                                                                                                                                                  const { error } = await supabase.from("products").delete().eq("id", id);
                                                                                                                                                                                                                                                                                                                                      setNotice(error ? `تعذّر الحذف: ${error.message}` : "تم حذف الصنف.");
                                                                                                                                                                                                                                                                                                                                          await loadData(); setBusy(false);
                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                              async function saveCategory(e: React.FormEvent) {
                                                                                                                                                                                                                                                                                                                                                  e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                      if (!supabase || !categoryName.trim()) return;
                                                                                                                                                                                                                                                                                                                                                          setBusy(true);
                                                                                                                                                                                                                                                                                                                                                              const { error } = await supabase.from("categories").insert({ name: categoryName.trim(), sort_order: categories.length + 1, is_active: true });
                                                                                                                                                                                                                                                                                                                                                                  setNotice(error ? `تعذّر إضافة القسم: ${error.message}` : "تمت إضافة القسم.");
                                                                                                                                                                                                                                                                                                                                                                      setCategoryName(""); setShowCategoryForm(false); await loadData(); setBusy(false);
                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                          async function uploadImage(file?: File) {
                                                                                                                                                                                                                                                                                                                                                                              if (!supabase || !file) return;
                                                                                                                                                                                                                                                                                                                                                                                  const extension = file.name.split(".").pop()?.toLowerCase() || "jpg";
                                                                                                                                                                                                                                                                                                                                                                                      const path = `${crypto.randomUUID()}.${extension}`;
                                                                                                                                                                                                                                                                                                                                                                                          setBusy(true); setNotice("");
                                                                                                                                                                                                                                                                                                                                                                                              const { error } = await supabase.storage.from("menu-images").upload(path, file, { upsert: false, contentType: file.type });
                                                                                                                                                                                                                                                                                                                                                                                                  if (error) setNotice(`تعذّر رفع الصورة: ${error.message}. تأكد من إنشاء bucket باسم menu-images وإضافة سياسات التخزين.`);
                                                                                                                                                                                                                                                                                                                                                                                                      else {
                                                                                                                                                                                                                                                                                                                                                                                                            const { data, error: urlError } = await supabase.storage
      .from("menu-images")
      .createSignedUrl(path, 60 * 60 * 24 * 365);

    if (urlError) throw urlError;
                                                                                                                                                                                                                                                                                                                                                                                                                  setForm(old => old ? { ...old, image_url: data.signedUrl } : old);
                                                                                                                                                                                                                                                                                                                                                                                                                        setNotice("تم رفع الصورة.");
                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                setBusy(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                    if (loading) return <main className="admin-page"><p>عم نجهّز لوحة الإدارة...</p></main>;
                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!supabase) return <main className="admin-page"><div className="admin-login"><Coffee size={35}/><h1>إعداد لوحة Soul Café</h1><p>أضف بيانات Supabase إلى ملف <code>.env.local</code> ثم أعد تشغيل المشروع. راجع README وملف schema.sql لإعداد قاعدة البيانات والصلاحيات.</p><a className="admin-back" href="/">العودة للمنيو</a></div></main>;

                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!signedIn) return <main className="admin-page"><form className="admin-login" onSubmit={login}>
                                                                                                                                                                                                                                                                                                                                                                                                                                            <Coffee size={35}/><span className="section-kicker">SOUL CAFÉ</span><h1>لوحة الإدارة</h1><p>سجّل الدخول بحساب المالك الذي أُنشئ في Supabase.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                <label>البريد الإلكتروني<input type="email" required value={email} onChange={e => setEmail(e.target.value)} autoComplete="username"/></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label>كلمة المرور<input type="password" required value={password} onChange={e => setPassword(e.target.value)} autoComplete="current-password"/></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                        {notice && <p className="admin-notice">{notice}</p>}<button className="checkout-btn" disabled={busy}>{busy ? "جارٍ الدخول..." : "تسجيل الدخول"}</button><a className="admin-back" href="/">العودة للمنيو</a>
                                                                                                                                                                                                                                                                                                                                                                                                                                                          </form></main>;

                                                                                                                                                                                                                                                                                                                                                                                                                                                            return <main className="admin-page">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                <header className="admin-header"><a className="brand admin-brand" href="/"><span className="brand-mark"><Coffee size={22}/></span><span><b>SOUL</b><small>ADMIN</small></span></a><div className="admin-header-actions"><button onClick={() => void loadData()} disabled={busy}><RefreshCw size={16}/> تحديث</button><button onClick={logout}><LogOut size={16}/> خروج</button></div></header>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <section className="admin-content">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="admin-title"><div><span className="section-kicker">CONTROL PANEL</span><h1>إدارة المنيو</h1><p>عدّل الأصناف والأسعار والأقسام. التغييرات تُحفظ في قاعدة البيانات.</p></div><button className="admin-primary" onClick={() => setForm(blankForm(categories[0]?.id || ""))}><Plus size={17}/> إضافة صنف</button></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {notice && <div className="admin-notice">{notice}</div>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="admin-stats"><div><span>الأصناف</span><b>{products.length}</b></div><div><span>المتوفرة</span><b>{products.filter(p => p.available).length}</b></div><div><span>الأقسام</span><b>{categories.length}</b></div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="admin-section-heading"><h2>الأصناف</h2><button onClick={() => setShowCategoryForm(v => !v)}><Plus size={15}/> إضافة قسم</button></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {showCategoryForm && <form className="category-add" onSubmit={saveCategory}><input value={categoryName} onChange={e => setCategoryName(e.target.value)} placeholder="اسم القسم الجديد" required/><button disabled={busy}>حفظ القسم</button><button type="button" onClick={() => setShowCategoryForm(false)}>إلغاء</button></form>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {form && <form className="product-editor" onSubmit={saveProduct}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="editor-heading"><h2>{form.id ? "تعديل صنف" : "إضافة صنف جديد"}</h2><button type="button" className="icon-button" onClick={() => setForm(null)}><X/></button></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="editor-grid">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <label>اسم الصنف<input required value={form.name} onChange={e => setForm({...form,name:e.target.value})}/></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <label>السعر<input required type="number" min="0" step="any" value={form.price} onChange={e => setForm({...form,price:e.target.value})}/></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <label>القسم<select required value={form.category_id} onChange={e => setForm({...form,category_id:e.target.value})}><option value="">اختر القسم</option>{categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <label>ترتيب العرض<input type="number" value={form.sort_order} onChange={e => setForm({...form,sort_order:e.target.value})}/></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <label className="full-field">الوصف<textarea rows={2} value={form.description} onChange={e => setForm({...form,description:e.target.value})}/></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label className="full-field">رابط الصورة<input value={form.image_url} onChange={e => setForm({...form,image_url:e.target.value})} placeholder="https://..."/></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <label className="upload-control"><ImagePlus size={17}/> أو ارفع صورة<input type="file" accept="image/*" onChange={e => void uploadImage(e.target.files?.[0])}/></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <label className="check-label"><input type="checkbox" checked={form.available} onChange={e => setForm({...form,available:e.target.checked})}/> متوفر في المنيو</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <label className="check-label"><input type="checkbox" checked={form.featured} onChange={e => setForm({...form,featured:e.target.checked})}/> صنف مميّز</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {form.image_url && <img className="image-preview" src={form.image_url} alt="معاينة صورة الصنف"/>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="editor-actions"><button className="admin-primary" disabled={busy}><Save size={16}/> حفظ</button><button type="button" onClick={() => setForm(null)}>إلغاء</button></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </form>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="admin-products">{products.map(p => <article className="admin-product" key={p.id}><img src={p.image_url || "https://placehold.co/100x100?text=Soul"} alt=""/><div className="admin-product-info"><b>{p.name}</b><span>{categories.find(c => c.id === p.category_id)?.name || "بدون قسم"}</span><strong>{formatPrice(Number(p.price))}</strong></div><span className={p.available ? "status-on" : "status-off"}>{p.available ? "متوفر" : "مخفي"}</span><button className="admin-icon" onClick={() => setForm({...p, featured: Boolean(p.featured), price:String(p.price), sort_order:String((p as Product & {sort_order?:number}).sort_order || 0)})} aria-label="تعديل"><Pencil size={17}/></button><button className="admin-icon danger" onClick={() => void deleteProduct(p.id)} aria-label="حذف"><Trash2 size={17}/></button></article>)}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <a className="admin-back" href="/">عرض المنيو العام ↗</a>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </main>;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  